// Small valid GIF89a fixtures with one and two image descriptors respectively.
const header = [
    0x47, 0x49, 0x46, 0x38, 0x39, 0x61,
    0x01, 0x00, 0x01, 0x00, 0x80, 0x00, 0x00,
    0x00, 0x00, 0x00, 0xff, 0xff, 0xff,
]
const frame = [
    0x21, 0xf9, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x2c, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00,
    0x02, 0x02, 0x4c, 0x01, 0x00,
]
export const staticGifBytes = Uint8Array.from([...header, ...frame, 0x3b])
export const animatedGifBytes = Uint8Array.from([...header, ...frame, ...frame, 0x3b])
